const $ = s => document.querySelector(s);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let workspace,activeProject='robot-1',isAdmin=false,shared=null;
let state, view='parts', editing=null, toastTimer;
let shopMode=false, wakeLock=null, keepAwake=false, previousView='parts';
let pendingStart=null,workflowFilter='all',workPart=null,workOriginal='';
try { const saved=localStorage.getItem(STORAGE_KEY); state=saved ? JSON.parse(saved):emptyWorkspace(); if(!validWorkspace(state)) throw new Error('Invalid workspace'); state=cleanSavedWorkspace(normalizeAssignments(state)); }
catch { state={version:1,parts:[],materials:[],cots:[],demo:false}; $('#save-status').textContent='Saved data could not be read. Restore a backup to recover your records.'; }
workspace=normalizeProjects(state);try{activeProject=localStorage.getItem('frc7028-active-project')||activeProject;}catch{}if(!workspace.projects.some(p=>p.id===activeProject&&!p.archived))activeProject=workspace.projects.find(p=>!p.archived).id;state=projectScope(workspace,activeProject);
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function loadShared(next){workspace=normalizeProjects(next);if(!workspace.projects.some(p=>p.id===activeProject&&!p.archived))activeProject=workspace.projects.find(p=>!p.archived).id;state=projectScope(workspace,activeProject);localStorage.setItem(STORAGE_KEY,JSON.stringify(workspace));refreshFilters();refreshProjectPicker();render();$('#save-status').textContent='Synced with team';$('.local-note').textContent='Shared team workspace';}
function saveWorkspace(next){if(!shared?.ready){toast('Shared workspace is connecting. Try again shortly.');return false;}if(!validWorkspace(next)){toast('Check project names and part data.');return false;}if(!shared.save(next))return false;workspace=next;state=projectScope(workspace,activeProject);localStorage.setItem(STORAGE_KEY,JSON.stringify(workspace));$('#save-status').textContent='Syncing with team';return true;}
function save(next){return saveWorkspace(mergeProject(workspace,next,activeProject));}
function refreshProjectPicker(){const options=workspace.projects.filter(p=>!p.archived).map(p=>'<option value="'+escape(p.id)+'">'+escape(p.name)+'</option>').join('');for(const id of ['project-picker','shop-project-picker']){const el=$('#'+id);el.innerHTML=options;el.value=activeProject;}}
function chooseProject(id){if(document.querySelector('dialog[open]'))return;if(!workspace.projects.some(p=>p.id===id&&!p.archived))return;activeProject=id;try{localStorage.setItem('frc7028-active-project',id);}catch{}state=projectScope(workspace,id);refreshProjectPicker();refreshFilters();switchView(view);}
function cleanSavedWorkspace(workspace){
 const result=cleanWorkspace(workspace);if(!result.changed)return workspace;
 try{const key=STORAGE_KEY+'-before-cleanup-v1';if(!localStorage.getItem(key))localStorage.setItem(key,JSON.stringify(workspace));localStorage.setItem(STORAGE_KEY,JSON.stringify(result.workspace));return result.workspace;}
 catch{toast('Cleanup could not be backed up. Your original records were kept.');return workspace;}
}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const overdue = p => overdueDays(p)>0;
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No deadline';
function filtered(){const term=$('#search').value.trim().toLowerCase();if(view==='cots')return state.cots.filter(i=>Object.values(i).join(' ').toLowerCase().includes(term)&&(!$('#status-filter').value||cotsStatus(i)===$('#status-filter').value)&&(!$('#subsystem-filter').value||vendorName(i.vendor)===$('#subsystem-filter').value));return (view==='inventory'?state.materials:state.parts).filter(r=>(view!=='board'||workflowMatches(r,workflowFilter,$('#workflow-worker').value))&&Object.values(r).join(' ').toLowerCase().includes(term) && (view==='inventory'||(!$('#status-filter').value||r.status===$('#status-filter').value)&&(!$('#tag-filter').value||($('#tag-filter').value==='overdue'?overdue(r):$('#tag-filter').value==='exceptions'?readinessException(r):$('#tag-filter').value==='ready'?readyToStartCutting(r):$('#tag-filter').value==='not-ready'?r.status!=='Finished'&&readinessIssues(r).length>0:Boolean(r.blocked)===($('#tag-filter').value==='blocked')))&&(!$('#subsystem-filter').value||r.subsystem===$('#subsystem-filter').value)));}
function render(){
 $('#onshape-target').textContent='BOM destination: '+(workspace.projects.find(p=>p.id===workspace.onshapeProjectId)?.name||'Disconnected');
 if(view==='projects'){renderProjects();return;}if(view==='admin'){renderAdmin();return;}$('#record-count').hidden=false;$('#special-panel').hidden=true;$('.content-panel').hidden=false;$('#workflow-bar').hidden=view!=='board';
 $('#sample-label').hidden=!state.demo||view==='cots';$('#clear-workspace').hidden=!state.demo;
 const summaryParts=view==='board'?filtered():state.parts;const stats=productionSummary(summaryParts);$('#board-summary').hidden=view!=='board';
 $('#board-summary').innerHTML='<div class="production-progress"><strong>'+stats.finished+' / '+stats.total+' pieces made</strong><span>'+stats.percent+'%</span><progress value="'+stats.finished+'" max="'+(stats.total||1)+'" aria-label="Finished pieces"></progress></div><div class="production-counts"><span>'+stats.jobsFinished+' / '+summaryParts.length+' batches made</span><span>'+summaryParts.filter(p=>p.status==='Finished'&&approvalStatus(p)!=='approved').length+' awaiting approval</span><span>'+summaryParts.filter(p=>approvalStatus(p)==='approved').length+' approved</span><span>'+stats.active+' active</span><span>'+stats.ready+' ready to start cutting</span><button class="summary-filter exception-count" data-summary-filter="exceptions">'+stats.exceptions+' readiness exception'+(stats.exceptions===1?'':'s')+'</button><button class="summary-filter overdue-count" data-summary-filter="overdue">'+stats.overdue+' overdue</button><span class="blocked-count">'+stats.blocked+' blocked</span></div>';
 $('#vendor-orders').hidden=view!=='cots'||!state.cots.some(i=>toOrder(i)>0);$('#vendor-orders').innerHTML=view==='cots'?vendorOrders(state.cots):'';
 $('#record-count').textContent=view==='cots'?state.cots.length:view==='inventory'?state.materials.length:state.parts.length;
 const rows=filtered(); $('#result-count').textContent=`Showing ${rows.length} of ${view==='cots'?state.cots.length:view==='inventory'?state.materials.length:state.parts.length} ${view==='inventory'?'materials':view==='cots'?'COTS parts':'parts'}`;
 if(view==='board'){$('#records').innerHTML=shopBoard(rows,dateLabel);return;}
 if(view==='cots'){$('#records').innerHTML=rows.length?cotsTable(rows):cotsEmptyState(state.cots.length);return;}
 if(!rows.length){$('#records').innerHTML='<div class="empty"><h3>No records here yet</h3>Add a record or adjust your search and filters.</div>';return;}
 if(view==='inventory'){$('#records').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Material / specification</th><th>On hand</th><th>Minimum</th><th>Location</th><th>Stock status</th></tr></thead><tbody>${rows.map(m=>`<tr><td><button class="part-name" data-edit="${escape(m.id)}">${escape(m.name)}</button><div class="part-number">${escape(m.spec)}</div></td><td>${m.stock} ${escape(m.unit)}</td><td>${m.minimum} ${escape(m.unit)}</td><td>${escape(m.location||'Unassigned')}</td><td><span class="status ${m.stock<=m.minimum?'blocked':'complete'}">${m.stock<=m.minimum?'Reorder soon':'In stock'}</span></td></tr>`).join('')}</tbody></table></div>`;return;}
 $('#records').innerHTML=partsRegister(rows);
}
function refreshFilters(){const old=$('#subsystem-filter').value,status=$('#status-filter').value;const cots=view==='cots';$('#status-filter').innerHTML='<option value="">'+(cots?'All statuses':'All stages')+'</option>'+(cots?COTS_STATUSES:STATUSES).map(s=>'<option>'+s+'</option>').join('');$('#status-filter').value=status;$('#subsystem-filter').setAttribute('aria-label',cots?'Filter by vendor':'Filter by subsystem');$('#status-filter').setAttribute('aria-label',cots?'Filter by order status':'Filter by stage');$('#subsystem-filter').innerHTML='<option value="">'+(cots?'All vendors':'All subsystems')+'</option>'+[...new Set(cots?state.cots.map(i=>vendorName(i.vendor)):state.parts.map(p=>p.subsystem).filter(Boolean))].sort().map(v=>'<option>'+escape(v)+'</option>').join('');$('#subsystem-filter').value=old;}
function switchView(next){
 view=['parts','board','cots','projects','admin'].includes(next)&&!(next==='admin'&&!isAdmin)?next:'parts';document.body.classList.toggle('production-view',view==='board');document.body.classList.toggle('register-view',view==='parts');
 document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 const inv=view==='inventory',board=view==='board',cots=view==='cots';
 $('#add-record').hidden=!isAdmin||['projects','admin'].includes(view);$('#page-title').textContent=cots?'COTS':inv?'Materials':board?'Production':'Parts';
 $('#add-record').textContent=cots?'Add COTS part':inv?'Add material':'Add part';$('#delete-record').textContent=inv?'Delete material':'Delete part';
 $('#search').placeholder=cots?'Search parts, vendors, or order numbers':inv?'Search materials':board?'Search parts or workers':'Search parts';
 workflowFilter='all';$('#search').value='';$('#status-filter').value='';$('#subsystem-filter').value='';$('#status-filter').hidden=!(board||cots);$('#tag-filter').hidden=inv||cots;$('#subsystem-filter').hidden=inv;$('#tag-filter').value='';refreshFilters();render();
}
const input=(name,label,type='text',value='',extra='')=>`<label ${name==='notes'||name==='name'?'class="full"':''}>${label}<input name="${name}" type="${type}" value="${escape(value)}" ${extra} maxlength="500"></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(s=>`<option ${s===value?'selected':''}>${escape(s)}</option>`).join('')}</select></label>`;
function edit(id){if(!isAdmin){openWork(id);return;}if(view==='cots'){cotsController.edit(id);return;}editing=id||null;const record=state.parts.find(r=>r.id===id)||{};
 $('#dialog-title').textContent=id?'Edit part':'Add part';$('#delete-record').hidden=!id;
 $('#form-fields').innerHTML=input('name','Part name','text',record.name,'required')+input('number','Part number','text',record.number)+input('subsystem','Subsystem','text',record.subsystem)+input('quantity','Batch quantity','number',record.quantity??1,'min="1" step="1" required')+input('assignedTo','Preassigned worker (optional)','text',record.assignedTo)+select('status','Manufacturing stage',STATUSES,record.status||'Not started')+select('priority','Priority',['Low','Normal','High'],record.priority||'Normal')+input('completedQty','Finished pieces','number',completedQuantity({...record,quantity:record.quantity||1})||0,'min="0" step="1" required')+input('material','Material','text',record.material)+input('process','Manufacturing process','text',record.process)+input('due','Due date','date',record.due)+input('cad','Drawing / CAD link','url',record.cad)+
 '<fieldset class="full readiness-checklist"><legend>Ready to manufacture</legend><p id="readiness-message">Complete these checks before cutting. Preparing can start while details are being gathered.</p>'+READINESS_CHECKS.map(([key,label])=>'<label><input type="checkbox" name="'+key+'" '+(record.readiness?.[key]?'checked':'')+'> '+escape(label)+'</label>').join('')+'</fieldset>'+`<label class="full blocked-field"><input name="blocked" type="checkbox" ${record.blocked?'checked':''}> <span>Blocked<small>Add the reason in shop notes.</small></span></label><label class="full">Shop notes<textarea name="notes" rows="3" maxlength="10000">${escape(record.notes||'')}</textarea></label>`+
 (record.history?.length?'<details class="full part-history"><summary>Recent activity</summary><ol>'+record.history.slice(-8).reverse().map(h=>'<li>'+escape(h.label)+'<small>'+escape(h.worker||'Team')+' · '+escape(new Date(h.at).toLocaleString())+'</small></li>').join('')+'</ol></details>':'');$('#record-dialog').showModal();
}
$('#form-fields').oninput=e=>{const affected={name:['drawingReviewed'],number:['drawingReviewed'],cad:['drawingReviewed'],material:['materialReady','setupReady'],quantity:['materialReady','setupReady'],process:['setupReady']}[e.target.name];for(const key of affected||[])$('#record-form').elements[key].checked=false;};
$('#record-form').addEventListener('submit',e=>{
 e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.keys(values).forEach(k=>values[k]=values[k].trim());const previous=state.parts.find(p=>p.id===editing);
 const readiness=Object.fromEntries(READINESS_CHECKS.map(([k])=>[k,e.target.elements[k].checked]));for(const [key] of READINESS_CHECKS)delete values[key];
 let part={...previous,...values,id:editing||crypto.randomUUID(),quantity:Number(values.quantity),completedQty:Number(values.completedQty),readiness,blocked:e.target.elements.blocked.checked,owner:values.assignedTo||(previous?.assignedTo?'':previous?.owner||'')};
 if(!validWorkspace({...state,parts:[part]})){toast('Check quantities, required fields and dates. Finished pieces cannot exceed the batch.');return;}
 if(part.assignedTo&&!workspace.students.some(s=>s.active&&s.name===part.assignedTo)){toast('Choose an active student for the advance assignment.');return;}
 const changing=part.status!==(previous?.status||'Not started');
 if(changing&&['Cutting','Finishing','Finished'].includes(part.status)&&readinessIssues(part).length){$('#readiness-message').textContent=readinessIssues(part).join(' ');$('#readiness-message').className='cart-error';toast('Complete the readiness checks before advancing.');return;}
 if(needsWorkerSelection(previous||{status:'Not started',owner:''},part.status)){editing=part.id;$('#record-dialog').close();beginWork(part,part.status);return;}
 try{part=changing?transitionPart({...part,status:previous?.status||'Not started'},part.status):logPartChange(part,{},previous?'Part updated':'Part created');}catch(err){toast(err.message);return;}
 const next={...state,parts:previous?state.parts.map(p=>p.id===part.id?part:p):[...state.parts,part]};if(save(next)){$('#record-dialog').close();refreshFilters();render();toast('Part saved');}
});

function commitStartedPart(part,worker='',target='Preparing'){
 const student=workspace.students.find(s=>s.active&&s.name.toLowerCase()===(part.assignedTo||worker).trim().toLowerCase());if(!student){toast('Choose an active student. An admin can add students in Admin.');return;}worker=student.name;
 const current=state.parts.find(p=>p.id===part.id);
 // Avoid replacing a newer record if another tab changes it while the picker is open.
 if(pendingStart&&JSON.stringify(current)!==pendingStart.original){toast('This part changed in another tab. Open it again before starting.');$('#start-dialog').close();return;}
 try{const assigned=startPart(part,worker,target);const started=transitionPart({...assigned,status:current?.status||'Not started'},target);const next={...state,parts:current?state.parts.map(p=>p.id===part.id?started:p):[...state.parts,started]};if(save(next)){pendingStart=null;$('#start-dialog').close();refreshFilters();render();toast(`Work started by ${started.owner}`);}}catch(err){toast(err.message);}
}
function beginWork(part,target){
 if(['Cutting','Finishing'].includes(target)&&readinessIssues(part).length){toast('Complete readiness checks before cutting.');openWork(part.id);return;}
 if(part.assignedTo?.trim()){commitStartedPart(part,'',target);return;}
 pendingStart={part,target,original:JSON.stringify(state.parts.find(p=>p.id===part.id))};
 $('#start-part-name').textContent=part.name;
 const names=workspace.students.filter(s=>s.active).map(s=>s.name).sort();
 $('#worker-choices').innerHTML=names.map(name=>`<button type="button" class="secondary" data-worker="${escape(name)}">${escape(name)}</button>`).join('');
 $('#worker-name').value=$('#workflow-worker').value.trim();$('#start-dialog').showModal();render();
}
function changeStatus(id,status){const part=state.parts.find(p=>p.id===id);if(!part||!STATUSES.includes(status))return;
 if(['Cutting','Finishing','Finished'].includes(status)&&readinessIssues(part).length){openWork(id);$('#work-error').textContent=readinessIssues(part).join(' ');return;}
 if(needsWorkerSelection(part,status)){beginWork(part,status);return;}
 try{const updated=transitionPart(part,status);if(save({...state,parts:state.parts.map(p=>p.id===id?updated:p)}))toast('Progress updated');}catch(err){toast(err.message);}render();}
$('#worker-choices').onclick=e=>{const button=e.target.closest('[data-worker]');if(button){$('#worker-name').value=button.dataset.worker;document.querySelectorAll('[data-worker]').forEach(b=>b.classList.toggle('selected',b===button));}};
$('#worker-name').oninput=()=>{document.querySelectorAll('[data-worker]').forEach(b=>b.classList.toggle('selected',b.dataset.worker===$('#worker-name').value));};
$('#start-form').onsubmit=e=>{e.preventDefault();if(pendingStart)commitStartedPart(pendingStart.part,$('#worker-name').value,pendingStart.target);};
['#cancel-start','#close-start'].forEach(s=>$(s).onclick=()=>$('#start-dialog').close());
$('#start-dialog').addEventListener('close',()=>{pendingStart=null;render();});
$('#delete-record').onclick=()=>{if(!isAdmin)return;if(!confirm('Delete this record? This cannot be undone.'))return;const key=view==='inventory'?'materials':'parts';if(save({...state,[key]:state[key].filter(r=>r.id!==editing)})){$('#record-dialog').close();refreshFilters();render();toast('Record deleted');}};
$('#records').onclick=e=>{if(e.target.closest('[data-clear-filters]')){$('#search').value='';$('#status-filter').value='';$('#subsystem-filter').value='';$('#tag-filter').value='';render();return;}if(e.target.closest('[data-add-cots]')){cotsController.edit();return;}const finish=e.target.closest('[data-finish-piece]');if(finish){const part=state.parts.find(p=>p.id===finish.dataset.finishPiece);try{const updated=recordCompletion(part,Math.min(part.quantity,completedQuantity(part)+1));if(save({...state,parts:state.parts.map(p=>p.id===part.id?updated:p)}))render();}catch(err){toast(err.message);}return;}const order=e.target.closest('[data-cots-order]'),received=e.target.closest('[data-cots-receive]');if(order||received){cotsController.quick((order||received).dataset[order?'cotsOrder':'cotsReceive'],Boolean(received));return;}const block=e.target.closest('[data-block]');if(block){openWork(block.dataset.block);return;}const advance=e.target.closest('[data-advance]');if(advance){changeStatus(advance.dataset.advance,advance.dataset.next);return;}const button=e.target.closest('[data-edit]');if(button){if(view==='cots')cotsController.edit(button.dataset.edit);else openWork(button.dataset.edit);}};
$('#records').onchange=e=>{if(e.target.dataset.status){changeStatus(e.target.dataset.status,e.target.value);}};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
$('#add-record').onclick=()=>edit();['#close-dialog','#cancel-dialog'].forEach(s=>$(s).onclick=()=>$('#record-dialog').close());['#search','#status-filter','#tag-filter','#subsystem-filter'].forEach(s=>$(s).addEventListener('input',render));
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>{const keys=view==='cots'?['name','vendor','number','needed','ordered','received','status','eta','reference','url','notes']:view==='inventory'?['name','spec','stock','minimum','unit','location']:['number','name','subsystem','status','blocked','quantity','completedQty','owner','assignedTo','due','priority','material','process','cad','notes'];download('\uFEFF'+csv([keys,...filtered().map(r=>keys.map(k=>view==='cots'&&k==='status'?cotsStatus(r):r[k]))]),'text/csv;charset=utf-8',`7028-${view}-${today()}.csv`);toast('CSV exported');};
try{$('#cleanup-backup').hidden=!localStorage.getItem(STORAGE_KEY+'-before-cleanup-v1');}catch{$('#cleanup-backup').hidden=true;}$('#cleanup-backup').onclick=()=>{const backup=localStorage.getItem(STORAGE_KEY+'-before-cleanup-v1');if(backup)download(backup,'application/json','7028-before-cleanup.json');};
$('#backup').onclick=()=>download(JSON.stringify(workspace,null,2),'application/json',`7028-workshop-${today()}.json`);
$('#restore').onclick=()=>{if(isAdmin)$('#import-file').click();};
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Backup must be under 5 MB.');const data=JSON.parse(await file.text());if(!validWorkspace(data))throw Error('This file is not a valid 7028 workspace backup.');if(confirm(`Replace this workspace with ${data.parts.length} parts, ${data.materials.length} materials, and ${data.cots?.length||0} COTS items? Back up current data first.`)&&saveWorkspace(cleanSavedWorkspace(normalizeAssignments(data)))){refreshFilters();render();toast('Workspace restored');}}catch(err){toast(err instanceof SyntaxError?'The file is not valid JSON.':err.message);}e.target.value='';};
const cotsController=initCots({canManage:()=>isAdmin,getWorkspace:()=>state,save,onChanged:()=>{refreshFilters();render();},toast});
$('#board-summary').onclick=e=>{const b=e.target.closest('[data-summary-filter]');if(b){$('#status-filter').value='';$('#tag-filter').value=b.dataset.summaryFilter;render();}};
$('#vendor-orders').onclick=e=>{const b=e.target.closest('[data-vendor-cart]');if(b)cotsController.cart(b.dataset.vendorCart);};
switchView('board');
shared=sharedWorkspace({getLocal:()=>workspace,onLoad:loadShared,onRole:value=>{isAdmin=value;refreshRecoveryButtons();$('#admin-tab').hidden=!value;$('#restore').hidden=!value;$('#open-onshape').hidden=!value;$('#add-record').hidden=!value;},onError:message=>{toast(message);refreshRecoveryButtons();}});
shared.start().then(()=>{if(isAdmin&&workspace.onshapeProjectId)initOnshape({enabled:()=>!!workspace.onshapeProjectId,getWorkspace:()=>projectScope(workspace,workspace.onshapeProjectId),save:next=>saveWorkspace(mergeProject(workspace,next,workspace.onshapeProjectId)),onChanged:()=>{refreshFilters();render();},toast});});
function updateShopTabs(){document.querySelectorAll('[data-shop-view]').forEach(b=>b.classList.toggle('selected',b.dataset.shopView===view));}
async function releaseWakeLock(){if(wakeLock){await wakeLock.release().catch(()=>{});wakeLock=null;}}
async function requestWakeLock(){if(!keepAwake||!shopMode||document.visibilityState!=='visible')return;try{if(!('wakeLock' in navigator))throw new Error('unsupported');wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null;$('#shop-awake').textContent=keepAwake?'Resume keep awake':'Keep awake';});$('#shop-awake').textContent='Display staying awake';}catch{keepAwake=false;$('#shop-awake').setAttribute('aria-pressed','false');$('#shop-awake').textContent='Keep awake';toast('Keep awake is unavailable. Use the smart board display settings.');}}
function setShopMode(enabled){if(enabled&&!shopMode)previousView=view;shopMode=enabled;document.body.classList.toggle('shop-mode',enabled);$('.shop-controls').hidden=!enabled;const url=new URL(location.href);if(enabled)url.searchParams.set('shop','1');else url.searchParams.delete('shop');history.replaceState(null,'',url);switchView(enabled?'board':previousView);updateShopTabs();if(!enabled){keepAwake=false;$('#shop-awake').setAttribute('aria-pressed','false');$('#shop-awake').textContent='Keep awake';releaseWakeLock();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}window.scrollTo(0,0);}
$('#enter-shop').onclick=()=>setShopMode(true);
$('#exit-shop').onclick=()=>setShopMode(false);
document.querySelectorAll('[data-shop-view]').forEach(b=>b.onclick=()=>{switchView(b.dataset.shopView);updateShopTabs();window.scrollTo(0,0);});
$('#shop-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else throw new Error('unsupported');}catch{toast('Fullscreen is unavailable here. Open the app in the smart board browser and use its fullscreen control.');}};
document.addEventListener('fullscreenchange',()=>$('#shop-fullscreen').textContent=document.fullscreenElement?'Leave fullscreen':'Fullscreen');
$('#shop-awake').onclick=async()=>{keepAwake=!keepAwake;$('#shop-awake').setAttribute('aria-pressed',String(keepAwake));if(keepAwake)await requestWakeLock();else{await releaseWakeLock();$('#shop-awake').textContent='Keep awake';}};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&keepAwake&&!wakeLock)requestWakeLock();});
let lastRenderedDate=today();
function updateClock(){if(today()!==lastRenderedDate){lastRenderedDate=today();render();}$('#shop-clock').textContent=new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}
updateClock();setInterval(updateClock,15000);
if(new URLSearchParams(location.search).get('shop')==='1')setShopMode(true);
$('#sample-label').hidden=!state.demo;
$('#clear-workspace').hidden=!state.demo;
$('#clear-workspace').onclick=()=>{if(confirm('Clear all parts, materials, and COTS items from this device? Download a backup first.')){if(save({version:1,demo:false,parts:[],materials:[],cots:[]})){$('#sample-label').hidden=true;$('#clear-workspace').hidden=true;refreshFilters();render();}}};
$('.tools-menu').addEventListener('click',e=>{if(e.target.closest('button'))$('.tools-menu').removeAttribute('open');});
$('#home').onclick=e=>{e.preventDefault();switchView('parts');};
function specialView(title){$('#record-count').hidden=true;$('#page-title').textContent=title;$('#special-panel').hidden=false;$('.content-panel').hidden=true;$('#board-summary').hidden=true;$('#vendor-orders').hidden=true;$('#workflow-bar').hidden=true;$('#record-count').textContent='';$('#add-record').hidden=true;$('#result-count').textContent='';}
function renderProjects(){specialView('Projects');$('#special-panel').innerHTML='<div class="project-grid">'+workspace.projects.filter(p=>!p.archived||isAdmin).map(p=>{const scope=projectScope(workspace,p.id),stats=productionSummary(scope.parts);return '<article class="project-tile"><h2>'+escape(p.name)+(p.archived?' <small>Removed</small>':'')+'</h2><p>'+scope.parts.length+' '+(scope.parts.length===1?'part':'parts')+' · '+scope.cots.length+' COTS '+(scope.cots.length===1?'item':'items')+'</p><p>'+stats.finished+' / '+stats.total+' pieces made</p><progress value="'+stats.finished+'" max="'+(stats.total||1)+'"></progress><div class="project-actions">'+(!p.archived?'<button class="primary" data-open-project="'+escape(p.id)+'">Open project</button>':'')+(isAdmin?'<button class="secondary" data-rename-project="'+escape(p.id)+'">Rename</button><button class="secondary" data-archive-project="'+escape(p.id)+'">'+(p.archived?'Restore':'Remove')+'</button>':'')+'</div></article>';}).join('')+'</div>'+(isAdmin?'<form id="new-project-form" class="project-create"><label>New project<input name="name" maxlength="100" required placeholder="Project name"></label><button class="primary">Create project</button></form><p class="helper">Removed projects retain their records and can be restored here.</p>':'<p class="helper">Only admins can create or remove projects.</p>');const form=$('#new-project-form');if(form)form.onsubmit=e=>{e.preventDefault();if(!isAdmin)return;const name=e.target.elements.name.value.trim();if(workspace.projects.some(p=>p.name.toLowerCase()===name.toLowerCase())){toast('That project name already exists.');return;}if(saveWorkspace({...workspace,projects:[...workspace.projects,{id:crypto.randomUUID(),name,archived:false}]})){refreshProjectPicker();renderProjects();}};}
function renderAdmin(){specialView('Admin');if(!isAdmin){$('#special-panel').textContent='Admin access is required.';return;}const waiting=workspace.parts.filter(p=>p.status==='Finished'&&approvalStatus(p)!=='approved');$('#special-panel').innerHTML='<section class="admin-section"><h2>Students</h2><form id="student-form" class="project-create"><label>Student name<input name="name" maxlength="100" required></label><button class="primary">Add student</button></form><div class="admin-parts">'+workspace.students.map(s=>'<div class="student-row"><strong>'+escape(s.name)+(s.active?'':' (removed)')+'</strong><button class="secondary" data-student-rename="'+escape(s.id)+'">Rename</button><button class="secondary" data-student-toggle="'+escape(s.id)+'">'+(s.active?'Remove':'Restore')+'</button></div>').join('')+'</div><p class="helper">Removing a student preserves past work and review history.</p></section><section class="admin-section"><h2>Review queue <span class="count">'+waiting.length+'</span></h2><p>Finished batches stay here until an admin approves them or returns them for changes.</p><form id="review-form">'+(waiting.length?'<button class="secondary" type="button" data-review-all>Select all</button><div class="review-list">'+waiting.map(p=>'<label class="review-item"><input type="checkbox" name="review" value="'+escape(p.id)+'"><span><strong>'+escape(p.name)+'</strong><small>'+escape(workspace.projects.find(x=>x.id===p.projectId)?.name||'Project')+' · '+escape(p.number)+' · '+completedQuantity(p)+' / '+p.quantity+' pieces</small><small>Worker: '+escape(p.owner||'Not recorded')+'</small><small>'+escape(p.material||'Material not recorded')+' · '+escape(p.process||'Process not recorded')+'</small>'+((p.cad&&/^https?:\/\//.test(p.cad))?'<a class="drawing-link" href="'+escape(p.cad)+'" target="_blank" rel="noopener noreferrer">Open drawing</a>':'')+'</span></label>').join('')+'</div><label>Reason / review note<textarea name="reason" maxlength="2000" placeholder="Required when returning work"></textarea></label><div class="project-actions"><button class="primary" name="decision" value="approved">Approve selected</button><button class="secondary" name="decision" value="changes_requested">Return for changes</button></div>':'<div class="empty">No batches awaiting review.</div>')+'</form></section><section class="admin-section"><h2>Project and BOM settings</h2><p>Only the approved, read-only Onshape BOM is used.</p><label>BOM destination<select id="bom-project-setting"><option value="">Disconnected</option>'+workspace.projects.filter(p=>!p.archived).map(p=>'<option value="'+escape(p.id)+'" '+(p.id===workspace.onshapeProjectId?'selected':'')+'>'+escape(p.name)+'</option>').join('')+'</select></label><button class="secondary" data-admin-projects>Manage projects</button><button class="secondary" data-admin-import>Onshape import</button><button class="secondary" data-admin-backup>Download full backup</button></section><section class="admin-section"><h2>Part details and assignments</h2><p>'+escape(workspace.projects.find(p=>p.id===activeProject)?.name)+'</p><button class="primary" data-admin-new>Add part</button><div class="admin-parts">'+state.parts.map(p=>'<button class="admin-part" data-admin-edit="'+escape(p.id)+'"><strong>'+escape(p.name)+'</strong><span>'+escape(p.number)+' · '+escape(p.assignedTo||'No advance assignment')+'</span></button>').join('')+'</div></section>';
 $('#student-form').onsubmit=e=>{e.preventDefault();const name=e.target.elements.name.value.trim();if(!name)return;if(workspace.students.some(s=>s.name.toLowerCase()===name.toLowerCase())){toast('This student already exists. Restore their roster entry if needed.');return;}if(saveWorkspace({...workspace,students:[...workspace.students,{id:crypto.randomUUID(),name,active:true}]}))renderAdmin();};
 $('#bom-project-setting').onchange=e=>{if(isAdmin&&saveWorkspace({...workspace,onshapeProjectId:e.target.value}))toast('BOM destination updated');};$('#review-form').onsubmit=async e=>{e.preventDefault();if(!isAdmin)return;const ids=new FormData(e.target).getAll('review'),decision=e.submitter.value,reason=e.target.elements.reason.value.trim();if(!ids.length){toast('Select at least one batch.');return;}if(decision==='changes_requested'&&!reason){toast('Add a reason for returning the work.');return;}e.submitter.disabled=true;try{await shared.review(ids,decision,reason);toast(decision==='approved'?'Selected batches approved':'Returned to Finishing with your review note');}catch(err){toast(err.message);e.submitter.disabled=false;}};
}
$('#special-panel').onclick=e=>{const target=e.target.closest('button');if(!target)return;const d=target.dataset;if(d.openProject){chooseProject(d.openProject);switchView('board');return;}if(!isAdmin)return;if('reviewAll'in d){document.querySelectorAll('#review-form input[name="review"]').forEach(el=>el.checked=true);return;}if(d.studentToggle){const student=workspace.students.find(s=>s.id===d.studentToggle);if(saveWorkspace({...workspace,students:workspace.students.map(s=>s.id===student.id?{...s,active:!s.active}:s),parts:workspace.parts.map(p=>student.active&&p.status!=='Finished'&&p.assignedTo===student.name?{...p,assignedTo:''}:p)}))renderAdmin();return;}if(d.studentRename){const student=workspace.students.find(s=>s.id===d.studentRename),name=prompt('Student name',student.name)?.trim();if(name&&saveWorkspace({...workspace,students:workspace.students.map(s=>s.id===student.id?{...s,name}:s),parts:workspace.parts.map(p=>({...p,owner:p.owner===student.name?name:p.owner,assignedTo:p.assignedTo===student.name?name:p.assignedTo}))}))renderAdmin();return;}if(d.archiveProject){const p=workspace.projects.find(p=>p.id===d.archiveProject);if(!p.archived&&workspace.onshapeProjectId===p.id){toast('Disconnect this project from the BOM in Admin before removing it.');return;}if(!p.archived&&workspace.projects.filter(p=>!p.archived).length===1){toast('Keep at least one active project.');return;}if(saveWorkspace({...workspace,projects:workspace.projects.map(x=>x.id===p.id?{...x,archived:!x.archived}:x)})){if(p.id===activeProject)chooseProject(workspace.projects.find(p=>!p.archived).id);refreshProjectPicker();render();}return;}if(d.renameProject){const p=workspace.projects.find(p=>p.id===d.renameProject),name=prompt('Project name',p.name)?.trim();if(name&&saveWorkspace({...workspace,projects:workspace.projects.map(x=>x.id===p.id?{...x,name}:x)})){refreshProjectPicker();render();}return;}if('adminProjects'in d)switchView('projects');if('adminImport'in d)$('#open-onshape').click();if('adminBackup'in d)$('#backup').click();if('adminNew'in d)edit();if(d.adminEdit)edit(d.adminEdit);};
function openWork(id){const p=state.parts.find(p=>p.id===id);if(!p)return;workPart=id;workOriginal=JSON.stringify(p);$('#work-title').textContent=p.name;$('#work-error').textContent='';$('#work-details').hidden=!isAdmin;const index=STATUSES.indexOf(p.status),next=STATUSES[index+1];$('#work-next').hidden=!next;$('#work-next').textContent=next==='Finished'?'Finish batch and submit for review':next?'Start '+next.toLowerCase():'';$('#work-fields').innerHTML='<p class="work-meta">'+escape(p.number)+' · '+escape(p.status)+' · '+escape(p.owner||p.assignedTo||'Unassigned')+'</p><p>'+escape(p.material||'Material needs admin setup')+' · '+escape(p.process||'Process needs admin setup')+'</p>'+((p.cad&&/^https?:\/\//.test(p.cad))?'<a class="drawing-link" href="'+escape(p.cad)+'" target="_blank" rel="noopener noreferrer">Open drawing</a>':'')+'<fieldset class="readiness-checklist"><legend>Ready to manufacture</legend>'+READINESS_CHECKS.map(([key,label])=>'<label><input name="'+key+'" type="checkbox" '+(p.readiness?.[key]?'checked':'')+'> '+escape(label)+'</label>').join('')+'</fieldset>'+(p.status==='Finishing'?'<label class="worker-name-label">Total finished pieces<input type="number" name="finished" min="0" max="'+p.quantity+'" step="1" value="'+completedQuantity(p)+'"></label>':'')+'<label class="work-block"><input type="checkbox" name="blocked" '+(p.blocked?'checked':'')+'> Blocked</label><label>Blocker / return reason<textarea name="blockReason" maxlength="2000">'+escape(p.blockReason||'')+'</textarea></label><label>Shop notes<textarea name="notes" maxlength="10000">'+escape(p.notes||'')+'</textarea></label>'+(p.approval?.reason?'<p class="review-return">Admin review: '+escape(p.approval.reason)+'</p>':'');if(p.approval)$('#work-fields').insertAdjacentHTML('beforeend','<p class="approval-receipt">'+(p.approval.status==='approved'?'Approved by '+escape(p.approval.reviewedBy)+' · '+escape(new Date(p.approval.reviewedAt).toLocaleString()):p.approval.status==='changes_requested'?'Returned for changes':'Awaiting admin approval')+'</p>');$('#work-dialog').showModal();}
$('#close-work').onclick=()=>$('#work-dialog').close();$('#work-details').onclick=()=>{const id=workPart;$('#work-dialog').close();if(isAdmin)edit(id);};$('#work-form').onsubmit=e=>{e.preventDefault();const current=state.parts.find(p=>p.id===workPart);if(!current||JSON.stringify(current)!==workOriginal){$('#work-error').textContent='This part changed. Close and reopen it before saving.';return;}const form=e.target,blocked=form.elements.blocked.checked,blockReason=form.elements.blockReason.value.trim();if(blocked&&!blockReason){$('#work-error').textContent='Add a reason so the next person knows what is blocking the job.';return;}let part=logPartChange(current,{readiness:Object.fromEntries(READINESS_CHECKS.map(([key])=>[key,form.elements[key].checked])),blocked,blockReason,notes:form.elements.notes.value.trim()},'Shop progress updated');try{if(form.elements.finished)part=recordCompletion(part,Number(form.elements.finished.value));if(e.submitter.value==='next'){const next=STATUSES[STATUSES.indexOf(part.status)+1];if(!next)return;if(['Cutting','Finishing','Finished'].includes(next)&&readinessIssues(part).length)throw Error(readinessIssues(part).join(' '));if(needsWorkerSelection(part,next)||(!part.assignedTo&&!workspace.students.some(s=>s.active&&s.name===part.owner))){ $('#work-dialog').close();beginWork(part,next);return;}part=transitionPart(part,next);}if(save({...state,parts:state.parts.map(p=>p.id===part.id?part:p)})){$('#work-dialog').close();render();toast(part.status==='Finished'?'Batch submitted to the review queue':'Progress saved');}}catch(err){$('#work-error').textContent=err.message;}};
$('#project-picker').onchange=e=>chooseProject(e.target.value);$('#shop-project-picker').onchange=e=>chooseProject(e.target.value);$('#workflow-bar').onclick=e=>{const b=e.target.closest('[data-flow]');if(b){workflowFilter=b.dataset.flow;render();}};$('#workflow-worker').oninput=()=>render();$('#next-job').onclick=()=>{const p=nextJob(state.parts,$('#workflow-worker').value);if(p)openWork(p.id);else toast('No unblocked job is available for this worker in this project.');};refreshProjectPicker();

function refreshRecoveryButtons(){try{$('#migration-backup').hidden=!localStorage.getItem('frc7028-before-shared-migration');$('#unsynced-backup').hidden=!localStorage.getItem('frc7028-unsynced-backup');}catch{}}
$('#migration-backup').onclick=()=>download(localStorage.getItem('frc7028-before-shared-migration'),'application/json','7028-before-shared-sync.json');$('#unsynced-backup').onclick=()=>download(localStorage.getItem('frc7028-unsynced-backup'),'application/json','7028-unsynced-changes.json');refreshRecoveryButtons();
